export const DEFAULT_MAX_JPEG_BYTES = 32 * 1024 * 1024;

export function jpegQualityToQ(quality: number): number {
  if (!Number.isFinite(quality)) throw new Error("JPEG quality must be finite");
  return Math.max(2, Math.round((100 - quality) / 8));
}

function findMarker(bytes: Uint8Array, marker: number, from: number): number {
  for (let index = Math.max(0, from); index + 1 < bytes.byteLength; index++) {
    if (bytes[index] === 0xff && bytes[index + 1] === marker) return index;
  }
  return -1;
}

export class JpegStreamParser {
  private buffer = new Uint8Array(0);
  private inFrame = false;
  private scanOffset = 0;

  constructor(private readonly maxFrameBytes = DEFAULT_MAX_JPEG_BYTES) {
    if (!Number.isInteger(maxFrameBytes) || maxFrameBytes < 4) throw new Error("invalid maximum JPEG size");
  }

  push(chunk: Uint8Array): Uint8Array[] {
    if (chunk.byteLength === 0) return [];
    if (this.buffer.byteLength === 0) {
      this.buffer = chunk.slice();
    } else {
      const joined = new Uint8Array(this.buffer.byteLength + chunk.byteLength);
      joined.set(this.buffer);
      joined.set(chunk, this.buffer.byteLength);
      this.buffer = joined;
    }

    const frames: Uint8Array[] = [];
    let position = 0;
    try {
      while (position < this.buffer.byteLength) {
        if (!this.inFrame) {
          const soi = findMarker(this.buffer, 0xd8, position);
          if (soi < 0) {
            position = Math.max(position, this.buffer.byteLength - 1);
            break;
          }
          position = soi;
          this.inFrame = true;
          this.scanOffset = position + 2;
        }

        const eoi = findMarker(this.buffer, 0xd9, this.scanOffset);
        if (eoi < 0) {
          this.scanOffset = Math.max(this.scanOffset, this.buffer.byteLength - 1);
          if (this.buffer.byteLength - position > this.maxFrameBytes) {
            throw new Error(`JPEG frame exceeds ${this.maxFrameBytes} bytes`);
          }
          break;
        }

        const end = eoi + 2;
        if (end - position > this.maxFrameBytes) throw new Error(`JPEG frame exceeds ${this.maxFrameBytes} bytes`);
        frames.push(this.buffer.slice(position, end));
        position = end;
        this.inFrame = false;
        this.scanOffset = position;
      }
    } catch (error) {
      this.buffer = new Uint8Array(0);
      this.inFrame = false;
      this.scanOffset = 0;
      throw error;
    }

    if (position > 0) {
      this.buffer = this.buffer.slice(position);
      this.scanOffset = this.inFrame ? Math.max(2, this.scanOffset - position) : 0;
    }
    return frames;
  }
}

export interface EncoderSink {
  write(data: Uint8Array): number | Promise<number>;
  flush?(): number | Promise<number>;
  end?(error?: Error): number | Promise<number>;
}

export interface EncoderProcess {
  readonly stdin: EncoderSink;
  readonly stdout: ReadableStream<Uint8Array>;
  readonly exited: Promise<number>;
  kill(signal?: NodeJS.Signals | number): void;
}

export type EncoderSpawn = (command: string[]) => EncoderProcess;

export interface JpegEncoderOptions {
  width: number;
  height: number;
  quality: number;
  ffmpeg?: string;
  maxFrameBytes?: number;
}

type Pending = { resolve: (jpeg: Uint8Array) => void; reject: (error: Error) => void };

function defaultSpawn(command: string[]): EncoderProcess {
  const proc = Bun.spawn(command, { stdin: "pipe", stdout: "pipe", stderr: "inherit" });
  if (!proc.stdin || typeof proc.stdin === "number") throw new Error("JPEG encoder stdin unavailable");
  if (!proc.stdout || typeof proc.stdout === "number") throw new Error("JPEG encoder stdout unavailable");
  return proc as unknown as EncoderProcess;
}

export class JpegEncoder {
  private readonly parser: JpegStreamParser;
  private readonly frameBytes: number;
  private readonly command: string[];
  private proc?: EncoderProcess;
  private pending?: Pending;
  private failure?: Error;
  private closed = false;
  private stopping?: Promise<void>;

  constructor(private readonly options: JpegEncoderOptions, private readonly spawn: EncoderSpawn = defaultSpawn) {
    const { width, height, quality } = options;
    if (!Number.isInteger(width) || width < 1 || !Number.isInteger(height) || height < 1) {
      throw new Error("invalid JPEG encoder dimensions");
    }
    this.frameBytes = width * height * 3;
    this.parser = new JpegStreamParser(options.maxFrameBytes);
    this.command = [
      options.ffmpeg ?? "ffmpeg", "-hide_banner", "-loglevel", "error",
      "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", `${width}x${height}`, "-i", "pipe:0",
      "-q:v", String(jpegQualityToQ(quality)), "-f", "image2pipe", "-vcodec", "mjpeg", "pipe:1",
    ];
  }

  start(): void {
    if (this.closed) throw new Error("JPEG encoder is stopped");
    if (this.proc) throw new Error("JPEG encoder already started");
    const proc = this.spawn(this.command);
    this.proc = proc;
    void this.read(proc);
    void proc.exited.then(
      code => this.handleExit(proc, code),
      error => { if (this.proc === proc && !this.closed) this.fail(error); },
    );
  }

  encode(bgr: Uint8Array): Promise<Uint8Array> {
    if (this.closed) return Promise.reject(new Error("JPEG encoder is stopped"));
    if (!this.proc) return Promise.reject(new Error("JPEG encoder is not started"));
    if (this.failure) return Promise.reject(this.failure);
    if (this.pending) return Promise.reject(new Error("JPEG encoder busy: another frame is being encoded"));
    if (bgr.byteLength !== this.frameBytes) {
      return Promise.reject(new Error(`JPEG encoder expected ${this.frameBytes} BGR bytes, got ${bgr.byteLength}`));
    }

    return new Promise<Uint8Array>((resolve, reject) => {
      const pending: Pending = { resolve, reject };
      this.pending = pending;
      try {
        const written = this.proc!.stdin.write(bgr);
        if (written instanceof Promise) {
          void written.then(
            count => { if (this.pending === pending && count !== bgr.byteLength) this.fail(new Error("JPEG encoder short input write")); },
            error => { if (this.pending === pending) this.fail(error); },
          );
        } else if (written !== bgr.byteLength) {
          this.fail(new Error("JPEG encoder short input write"));
        }
      } catch (error) {
        if (this.pending === pending) this.fail(error);
      }
    });
  }

  stop(): Promise<void> {
    if (this.stopping) return this.stopping;
    this.closed = true;
    const proc = this.proc;
    this.proc = undefined;
    const failure = this.failure ?? new Error("JPEG encoder stopped");
    this.failure = failure;
    this.rejectPending(failure);
    if (!proc) return Promise.resolve();

    try {
      const ended = proc.stdin.end?.();
      if (ended instanceof Promise) void ended.catch(() => undefined);
    } catch { /* stdin already closed */ }
    try { proc.kill("SIGTERM"); } catch { /* process already exited */ }

    this.stopping = Promise.race([
      proc.exited.then(() => undefined, () => undefined),
      Bun.sleep(1000),
    ]).then(() => { this.stopping = undefined; });
    return this.stopping;
  }

  private async read(proc: EncoderProcess): Promise<void> {
    const reader = proc.stdout.getReader();
    try {
      while (!this.closed) {
        const { value, done } = await reader.read();
        if (done) break;
        const frames = this.parser.push(value);
        for (const frame of frames) this.settle(frame);
      }
    } catch (error) {
      if (!this.closed && this.proc === proc) this.fail(error);
    } finally {
      try { reader.releaseLock(); } catch { /* already released */ }
    }
    if (!this.closed && this.proc === proc && !this.failure) this.fail(new Error("JPEG encoder stdout closed"));
  }

  private settle(frame: Uint8Array): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    pending.resolve(frame);
  }

  private rejectPending(error: Error): void {
    const pending = this.pending;
    this.pending = undefined;
    pending?.reject(error);
  }

  private fail(error: unknown): void {
    if (this.closed) return;
    const failure = error instanceof Error ? error : new Error(String(error));
    if (!this.failure) this.failure = failure;
    this.rejectPending(this.failure);
    const proc = this.proc;
    if (proc) { try { proc.kill("SIGTERM"); } catch { /* process already exited */ } }
  }

  private handleExit(proc: EncoderProcess, code: number): void {
    if (this.proc !== proc || this.closed) return;
    this.fail(new Error(`JPEG encoder exited with code ${code}`));
  }
}

export interface ManagedProcess {
  readonly pid: number;
  readonly exited: Promise<number>;
  kill(signal?: NodeJS.Signals | number): void;
}

export interface WorkerSupervisorOptions {
  spawn: () => ManagedProcess;
  now?: () => number;
  watchdogMs?: number;
  startupMs?: number;
  restartMs?: number;
  checkMs?: number;
  termMs?: number;
  stopMs?: number;
  killGroup?: (pid: number, signal: NodeJS.Signals) => void;
  onEvent?: (event: string, detail?: unknown) => void;
}

/** Supervises one inference worker. It never owns the IPC socket. */
export class WorkerSupervisor {
  private process?: ManagedProcess;
  private terminating?: ManagedProcess;
  private timer?: ReturnType<typeof setInterval>;
  private restartTimer?: ReturnType<typeof setTimeout>;
  private generation = 0;
  private stopping = false;
  private latched = false;
  private stopPromise?: Promise<void>;
  private startedAt = 0;
  private lastFrameAt = 0;
  private readonly now: () => number;
  private readonly watchdogMs: number;
  private readonly startupMs: number;
  private readonly restartMs: number;
  private readonly checkMs: number;
  private readonly termMs: number;
  private readonly stopMs: number;
  private readonly killGroup: (pid: number, signal: NodeJS.Signals) => void;

  constructor(private readonly options: WorkerSupervisorOptions) {
    this.now = options.now ?? Date.now;
    this.watchdogMs = options.watchdogMs ?? 5_000;
    this.startupMs = options.startupMs ?? 15_000;
    this.restartMs = options.restartMs ?? 1_000;
    this.checkMs = options.checkMs ?? 1_000;
    this.termMs = options.termMs ?? 2_000;
    this.stopMs = options.stopMs ?? 2_500;
    this.killGroup = options.killGroup ?? ((pid, signal) => process.kill(-pid, signal));
  }

  start(): void {
    if (this.stopPromise || this.latched) return;
    if (this.process || this.terminating || this.restartTimer) return;
    this.stopping = false;
    this.spawn();
    this.timer ??= setInterval(() => this.check(), this.checkMs);
  }

  noteFrame(at = this.now()): void { this.lastFrameAt = at; }

  private spawn(): void {
    if (this.stopping) return;
    const generation = ++this.generation;
    const child = this.options.spawn();
    this.process = child;
    this.startedAt = this.now();
    this.lastFrameAt = 0;
    this.options.onEvent?.('spawn', { pid: child.pid });
    const settle = (event: string, detail: unknown) => {
      if (this.process === child) this.process = undefined;
      if (this.terminating === child) this.terminating = undefined;
      this.latched = false;
      this.options.onEvent?.(event, detail);
      if (!this.stopping && generation === this.generation) this.scheduleRestart();
    };
    void child.exited.then(
      code => settle('exit', { pid: child.pid, code }),
      error => settle('error', error),
    );
  }

  private scheduleRestart(): void {
    if (this.restartTimer || this.stopping) return;
    this.restartTimer = setTimeout(() => {
      this.restartTimer = undefined;
      this.spawn();
    }, this.restartMs);
  }

  private check(): void {
    const child = this.process;
    if (!child || this.stopping || this.terminating === child) return;
    const age = this.now() - (this.lastFrameAt || this.startedAt);
    const limit = this.lastFrameAt ? this.watchdogMs : this.startupMs;
    if (age <= limit) return;
    this.options.onEvent?.('watchdog', { pid: child.pid, age });
    this.terminate(child);
  }

  private signal(child: ManagedProcess, signal: NodeJS.Signals): void {
    try { this.killGroup(child.pid, signal); }
    catch { try { child.kill(signal); } catch { /* already exited or group gone */ } }
  }

  private terminate(child: ManagedProcess): void {
    if (this.terminating === child) return;
    this.terminating = child;
    this.signal(child, 'SIGTERM');
    let exited = false;
    const escalation = setTimeout(() => {
      if (exited || this.terminating !== child) return;
      this.signal(child, 'SIGKILL');
    }, this.termMs);
    const clear = () => { exited = true; clearTimeout(escalation); };
    void child.exited.then(clear, clear);
  }

  stop(): Promise<void> {
    if (this.stopPromise) return this.stopPromise;
    this.stopping = true;
    this.generation++;
    if (this.timer) clearInterval(this.timer);
    if (this.restartTimer) clearTimeout(this.restartTimer);
    this.timer = undefined;
    this.restartTimer = undefined;

    const child = this.process ?? this.terminating;
    if (!child) {
      this.stopPromise = Promise.resolve().then(() => { this.stopPromise = undefined; });
      return this.stopPromise;
    }

    this.terminate(child);
    let settled = false;
    const onExit = () => { settled = true; };
    void child.exited.then(onExit, onExit);
    const waitMs = Math.max(this.stopMs, this.termMs + 100);
    this.stopPromise = Promise.race([
      child.exited.then(() => undefined, () => undefined),
      Bun.sleep(waitMs),
    ]).then(() => {
      if (settled) {
        if (this.process === child) this.process = undefined;
        if (this.terminating === child) this.terminating = undefined;
        this.latched = false;
      } else {
        this.latched = true;
      }
      this.stopPromise = undefined;
    });
    return this.stopPromise;
  }

  get pid(): number | undefined { return this.process?.pid; }
}

export type Box = { label: string; confidence: number; x: number; y: number; width: number; height: number };
export type Strategy = 'confidence' | 'area' | 'confidence + area';
export function chooseTarget(boxes: Box[], label: string, strategy: Strategy): Box | null {
  const matches = boxes.filter(b => b.label === label && b.width > 0 && b.height > 0);
  const largest = Math.max(1, ...matches.map(b => b.width * b.height));
  return matches.toSorted((a, b) => {
    const score = (v: Box) => strategy === 'confidence' ? v.confidence : strategy === 'area' ? v.width * v.height / largest : (v.confidence + v.width * v.height / largest) / 2;
    return score(b) - score(a);
  })[0] ?? null;
}
export class Tracker {
  enabled = false; label = ''; strategy: Strategy = 'confidence + area';
  aimX = 0.5; aimY = 0.5; misses = 0;
  update(boxes: Box[], width: number, height: number, ageMs: number, yawLimit: boolean): { yaw: number; pitch: number } {
    if (!this.enabled || ageMs > 300) return { yaw: 0, pitch: 0 };
    const box = chooseTarget(boxes, this.label, this.strategy);
    if (!box) { this.misses++; return { yaw: 0, pitch: 0 }; }
    this.misses = 0;
    const dx = box.x + box.width / 2 - this.aimX * width;
    const dy = box.y + box.height / 2 - this.aimY * height;
    return {
      yaw: yawLimit || Math.abs(dx) < 12 ? 0 : Math.max(-1600, Math.min(1600, dx * 2.5)),
      pitch: Math.abs(dy) < 12 ? 0 : Math.max(-1000, Math.min(1000, dy * 2))
    };
  }
}

export type Config = {
  host: string; port: number; socket: string; model: string; camera: string;
  width: number; height: number; fps: number; jpegQuality: number;
  relayActiveHigh: boolean | null; yawNegativeSwitch: string | null;
  maxPumpMs: number; pulseMs: number; maxSteps: number;
};

const number = (name: string, fallback: number, min: number, max: number) => {
  const value = Number(process.env[name] ?? fallback);
  if (!Number.isFinite(value) || value < min || value > max) throw new Error(`${name} must be ${min}..${max}`);
  return value;
};

export function loadConfig(): Config {
  const polarity = process.env.KITTI_RELAY_ACTIVE_HIGH;
  if (polarity !== undefined && polarity !== '0' && polarity !== '1') throw new Error('KITTI_RELAY_ACTIVE_HIGH must be 0 or 1');
  return {
    host: process.env.KITTI_HOST ?? '127.0.0.1',
    port: number('KITTI_PORT', 8080, 1, 65535),
    socket: process.env.KITTI_SOCKET ?? '/tmp/kitti-turret.sock',
    model: process.env.KITTI_MODEL ?? '', camera: process.env.KITTI_CAMERA ?? 'auto',
    width: number('KITTI_WIDTH', 640, 64, 4096), height: number('KITTI_HEIGHT', 480, 64, 4096),
    fps: number('KITTI_FPS', 20, 1, 120), jpegQuality: number('KITTI_JPEG_QUALITY', 60, 1, 100),
    relayActiveHigh: polarity === undefined ? null : polarity === '1',
    yawNegativeSwitch: process.env.KITTI_YAW_NEGATIVE_SWITCH ?? null,
    maxPumpMs: number('KITTI_MAX_PUMP_MS', 10000, 50, 60000),
    pulseMs: number('KITTI_PULSE_MS', 500, 50, 2000),
    maxSteps: number('KITTI_MAX_STEPS', 57600, 1, 1000000)
  };
}

import type {DigitalIo,Pin} from './gpio';
import {Stepper} from './stepper';
import {Pump} from './pump';
export type Axis='yaw'|'pitch';
export interface LimitConfig {negative:Pin;positive:Pin;graceSteps:number;backoffSteps:number;backoffRate:number;maxBackoffSteps:number}
export const DEFAULT_LIMITS:LimitConfig={negative:'GPIO1_B6',positive:'GPIO1_B7',graceSteps:64,backoffSteps:128,backoffRate:960,maxBackoffSteps:2400};
export class Manual {
 enabled=false; speedPct=100; estopped=false;
 private running=new Map<Axis,Promise<void>>();
 private generation:Record<Axis,number>={yaw:0,pitch:0};
 constructor(readonly axes:Record<Axis,Stepper>,readonly pump:Pump,private io:DigitalIo,readonly limits:LimitConfig=DEFAULT_LIMITS){
  if(limits.negative===limits.positive)throw new Error('Limit pins must differ');
  io.input(limits.negative,true);io.input(limits.positive,true);
 }
 switches(){return {negative:this.io.read(this.limits.negative),positive:this.io.read(this.limits.positive)};}
 enable(on:boolean){if(this.estopped&&on)throw new Error('E-stop active');if(on){for(const a of Object.values(this.axes))a.enable();this.enabled=true;}else{this.stop();for(const a of Object.values(this.axes))a.forceDisable();this.enabled=false;}}
 speed(pct:number){if(!Number.isFinite(pct)||pct<10||pct>200)throw new Error('Speed out of range');this.speedPct=pct;}
 stop(axis?:Axis){for(const [name,m] of Object.entries(this.axes) as [Axis,Stepper][])if(!axis||axis===name){this.generation[name]++;m.cancel();}}
 async start(axis:Axis,dir:1|-1,slow=false){
  if(!this.enabled||this.estopped)throw new Error('Motor disabled');
  if(this.running.has(axis)){this.stop(axis);await this.running.get(axis);}
  const id=++this.generation[axis];
  const motor=this.axes[axis];
  const base=axis==='yaw'?1920:1280;
  const rate=base*this.speedPct/100*(slow?.25:1);
  const task=(async()=>{
   let moved=0;
   const atStart=axis==='yaw'?this.switches():undefined;
   const blocking=dir<0?'negative':'positive';
   const opposite=dir<0?'positive':'negative';
   while(id===this.generation[axis]&&moved<motor.cfg.maxSteps&&this.enabled&&!this.estopped){
    if(axis==='yaw'){
     const now=this.switches();
     if(now[blocking])break;
     if(now[opposite]&&moved>=this.limits.graceSteps&&atStart?.[opposite])break;
    }
    const n=await motor.move(dir,Math.min(32,motor.cfg.maxSteps-moved),rate,axis==='yaw'?()=>{const sw=this.switches();return sw[blocking]||(moved>=this.limits.graceSteps&&!!atStart?.[opposite]&&sw[opposite]);}:undefined);
    moved+=n;if(n===0)break;
   }
   if(axis==='yaw'&&id===this.generation[axis]&&this.enabled&&!this.estopped){
    const hit=this.switches()[blocking]&&!atStart?.[blocking];
    if(hit){const n=Math.min(this.limits.backoffSteps,this.limits.maxBackoffSteps);await motor.move(dir===1?-1:1,n,this.limits.backoffRate);}
   }
  })();
  this.running.set(axis,task);try{await task;}finally{if(this.running.get(axis)===task)this.running.delete(axis);}
 }
 estop(){this.estopped=true;this.stop();this.pump.estop();for(const a of Object.values(this.axes))a.forceDisable();this.enabled=false;}
 resetEstop(){this.estopped=false;this.pump.resetEstop();}
 shutdown(){this.estop();}
}

import { test, expect } from 'bun:test';
import { PacketDecoder, PacketType, encodePacket, FrameWindow } from '../src/ipc';
import { chooseTarget, Tracker } from '../src/tracking';
import { loadConfig } from '../src/config';

test('packet decoder handles split headers and payloads', () => {
  const bytes = encodePacket(PacketType.Detection, new TextEncoder().encode('ok'));
  const decoder = new PacketDecoder();
  expect(decoder.push(bytes.slice(0, 2))).toEqual([]);
  expect(decoder.push(bytes.slice(2, 6))).toEqual([]);
  expect(new TextDecoder().decode(decoder.push(bytes.slice(6))[0]!.payload)).toBe('ok');
});
test('frame window drops oldest queued and detects stale ack', () => {
  const window = new FrameWindow();
  for (let i = 0; i < 3; i++) window.offer(i, new Uint8Array([i]));
  expect(window.dropped).toBe(1);
  const sent: number[] = [];
  window.flush(data => sent.push(data[0]!), 0);
  expect(sent).toEqual([1, 2]);
  expect(window.inFlight).toBe(2);
  expect(window.stalled(30001)).toBe(true);
  window.ack(1); window.ack(2);
  expect(window.stalled(30001)).toBe(false);
});
test('tracking box contract uses width and height for the center and area', () => {
  const tracker = new Tracker(); tracker.enabled = true; tracker.label = 'cat';
  const box = { label: 'cat', confidence: 0.9, x: 400, y: 300, width: 80, height: 100 };
  expect(tracker.update([box], 640, 480, 10, false)).toEqual({ yaw: 300, pitch: 220 });
  const boxes = [
    { label: 'cat', confidence: 0.99, x: 0, y: 0, width: 10, height: 10 },
    { label: 'cat', confidence: 0.10, x: 0, y: 0, width: 100, height: 100 },
    { label: 'cat', confidence: 0.90, x: 0, y: 0, width: 0, height: 100 },
  ];
  expect(chooseTarget(boxes, 'cat', 'area')?.width).toBe(100);
  expect(chooseTarget([boxes[2]!], 'cat', 'confidence')).toBeNull();
});
test('tracking ignores stale boxes and limit prevents yaw', () => {
  const tracker = new Tracker(); tracker.enabled = true; tracker.label = 'cat';
  const box = { label: 'cat', confidence: 0.9, x: 400, y: 200, width: 80, height: 80 };
  expect(tracker.update([box], 640, 480, 301, false)).toEqual({ yaw: 0, pitch: 0 });
  expect(tracker.update([box], 640, 480, 10, true).yaw).toBe(0);
  expect(tracker.update([box], 640, 480, 10, false).yaw).toBeGreaterThan(0);
  expect(chooseTarget([box], 'dog', 'area')).toBeNull();
});
test('relay polarity is unconfigured by default', () => {
  expect(loadConfig().relayActiveHigh).toBeNull();
});

import { expect, test } from 'bun:test';
import { WorkerSupervisor, type ManagedProcess } from '../src/supervisor';

class FakeProcess implements ManagedProcess {
  private resolve!: (code: number) => void;
  readonly exited = new Promise<number>(resolve => { this.resolve = resolve; });
  readonly signals: (NodeJS.Signals | number | undefined)[] = [];
  constructor(readonly pid: number) {}
  kill(signal?: NodeJS.Signals | number): void { this.signals.push(signal); }
  exit(code = 0): void { this.resolve(code); }
}

function harness(overrides: Partial<ConstructorParameters<typeof WorkerSupervisor>[0]> = {}) {
  let now = 0;
  const children: FakeProcess[] = [];
  const groupSignals: [number, NodeJS.Signals][] = [];
  const supervisor = new WorkerSupervisor({
    now: () => now,
    checkMs: 2,
    watchdogMs: 10,
    startupMs: 10,
    restartMs: 2,
    termMs: 20,
    stopMs: 50,
    spawn: () => { const child = new FakeProcess(100 + children.length); children.push(child); return child; },
    killGroup: (pid, signal) => { groupSignals.push([pid, signal]); },
    ...overrides,
  });
  return { supervisor, children, groupSignals, tick: (value: number) => { now = value; } };
}

test('watchdog sends one TERM then escalates to KILL before restarting', async () => {
  const { supervisor, children, groupSignals, tick } = harness();
  supervisor.start();
  expect(supervisor.pid).toBe(100);
  tick(11);
  await Bun.sleep(5);
  expect(groupSignals).toEqual([[100, 'SIGTERM']]);
  await Bun.sleep(10);
  expect(groupSignals).toEqual([[100, 'SIGTERM']]);
  await Bun.sleep(25);
  expect(groupSignals).toEqual([[100, 'SIGTERM'], [100, 'SIGKILL']]);
  children[0]!.exit(1);
  await Bun.sleep(8);
  expect(supervisor.pid).toBe(101);
  const stopping = supervisor.stop();
  children[1]!.exit(0);
  await stopping;
});

import { connect } from "bun";
import { Camera } from "./camera";
import { loadConfig } from "./config";
import { PacketDecoder, PacketType, FrameWindow, encodePacket } from "./ipc";
import { letterbox } from "./preprocess";
import { RknnModel, NpuLock } from "./rknn";
import { decodeFp16 } from "./yolo";
import { TagHelper } from "./apriltag";

const config = loadConfig();
if (!config.model) throw new Error("KITTI_MODEL must identify an RKNN model");
const camera = new Camera({ device: config.camera === "auto" ? undefined : config.camera, width: config.width, height: config.height, fps: config.fps });
const model = new RknnModel(config.model);
const npuLock = new NpuLock();
const tags = new TagHelper();
const decoder = new PacketDecoder(), window = new FrameWindow();
const classes = new Set([0, 15, 16]);
let socket: Awaited<ReturnType<typeof connect>> | undefined, running = true;
process.once('SIGINT', () => { running = false; });
process.once('SIGTERM', () => { running = false; });

async function jpeg(bgr: Uint8Array): Promise<Uint8Array> {
  const proc = Bun.spawn(["ffmpeg", "-hide_banner", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", `${config.width}x${config.height}`, "-i", "pipe:0", "-frames:v", "1", "-q:v", String(Math.max(2, Math.round((100 - config.jpegQuality) / 8))), "-f", "image2", "-vcodec", "mjpeg", "pipe:1"], { stdin: "pipe", stdout: "pipe", stderr: "inherit" });
  proc.stdin.write(bgr); proc.stdin.end();
  const bytes = await new Response(proc.stdout).arrayBuffer();
  if (await proc.exited !== 0) throw new Error("JPEG encoder failed");
  return new Uint8Array(bytes);
}

async function main(): Promise<void> {
  npuLock.acquire();
  await model.open(); await camera.start(); tags.start();
  socket = await connect({ unix: config.socket, socket: {
    data(_socket, bytes) {
      for (const packet of decoder.push(bytes)) {
        if (packet.type === PacketType.Ack && packet.payload.length >= 4) window.ack(new DataView(packet.payload.buffer, packet.payload.byteOffset).getUint32(0, true));
        if (packet.type === PacketType.Control) {
          try { const command = JSON.parse(new TextDecoder().decode(packet.payload)); if (command.type === "classes" && Array.isArray(command.ids)) { classes.clear(); for (const id of command.ids) if (Number.isInteger(id) && id >= 0 && id < 80) classes.add(id); } }
          catch (error) { console.warn("invalid worker control", error); }
        }
      }
    }, close() { running = false; }, error(_socket, error) { console.error("IPC error", error); running = false; }
  } });
  let lastSeq = 0;
  while (running) {
    const frame = camera.takeLatest();
    if (!frame || frame.sequence === lastSeq) { await Bun.sleep(2); continue; }
    lastSeq = frame.sequence;
    tags.submit(frame.sequence, frame.bgr, frame.width, frame.height);
    const result = letterbox(frame.bgr, frame.width, frame.height);
    const raw = await model.infer(result.rgb);
    const boxes = [...decodeFp16(raw, result, classes), ...tags.latest()];
    const detection = new TextEncoder().encode(JSON.stringify({ sequence: frame.sequence, timestamp: frame.capturedAt, width: frame.width, height: frame.height, boxes, dropped: camera.dropped + window.dropped }));
    socket.write(encodePacket(PacketType.Detection, detection));
    const image = await jpeg(frame.bgr);
    const payload = new Uint8Array(12 + image.length), view = new DataView(payload.buffer);
    view.setUint32(0, frame.sequence, true); view.setBigUint64(4, BigInt(frame.capturedAt), true); payload.set(image, 12);
    window.offer(frame.sequence, encodePacket(PacketType.Frame, payload));
    window.flush(data => socket!.write(data));
    if (window.stalled()) throw new Error("frame ack timeout");
  }
}
try { await main(); } finally { camera.stop(); tags.stop(); model.close(); socket?.end(); npuLock.release(); }

export const DEFAULT_MAX_JPEG_BYTES = 32 * 1024 * 1024;

export function jpegQualityToQ(quality: number): number {
  if (!Number.isFinite(quality)) throw new Error("JPEG quality must be finite");
  return Math.max(2, Math.round((100 - quality) / 8));
}

function findMarker(bytes: Uint8Array, marker: number, from: number): number {
  for (let index = Math.max(0, from); index + 1 < bytes.byteLength; index++) {
    if (bytes[index] === 0xff && bytes[index + 1] === marker) return index;
  }
  return -1;
}

export class JpegStreamParser {
  private buffer = new Uint8Array(0);
  private inFrame = false;
  private scanOffset = 0;

  constructor(private readonly maxFrameBytes = DEFAULT_MAX_JPEG_BYTES) {
    if (!Number.isInteger(maxFrameBytes) || maxFrameBytes < 4) throw new Error("invalid maximum JPEG size");
  }

  push(chunk: Uint8Array): Uint8Array[] {
    if (chunk.byteLength === 0) return [];
    if (this.buffer.byteLength === 0) {
      this.buffer = chunk.slice();
    } else {
      const joined = new Uint8Array(this.buffer.byteLength + chunk.byteLength);
      joined.set(this.buffer);
      joined.set(chunk, this.buffer.byteLength);
      this.buffer = joined;
    }

    const frames: Uint8Array[] = [];
    let position = 0;
    try {
      while (position < this.buffer.byteLength) {
        if (!this.inFrame) {
          const soi = findMarker(this.buffer, 0xd8, position);
          if (soi < 0) {
            position = Math.max(position, this.buffer.byteLength - 1);
            break;
          }
          position = soi;
          this.inFrame = true;
          this.scanOffset = position + 2;
        }

        const eoi = findMarker(this.buffer, 0xd9, this.scanOffset);
        if (eoi < 0) {
          this.scanOffset = Math.max(this.scanOffset, this.buffer.byteLength - 1);
          if (this.buffer.byteLength - position > this.maxFrameBytes) {
            throw new Error(`JPEG frame exceeds ${this.maxFrameBytes} bytes`);
          }
          break;
        }

        const end = eoi + 2;
        if (end - position > this.maxFrameBytes) throw new Error(`JPEG frame exceeds ${this.maxFrameBytes} bytes`);
        frames.push(this.buffer.slice(position, end));
        position = end;
        this.inFrame = false;
        this.scanOffset = position;
      }
    } catch (error) {
      this.buffer = new Uint8Array(0);
      this.inFrame = false;
      this.scanOffset = 0;
      throw error;
    }

    if (position > 0) {
      this.buffer = this.buffer.slice(position);
      this.scanOffset = this.inFrame ? Math.max(2, this.scanOffset - position) : 0;
    }
    return frames;
  }
}

export interface EncoderSink {
  write(data: Uint8Array): number | Promise<number>;
  flush?(): number | Promise<number>;
  end?(error?: Error): number | Promise<number>;
}

export interface EncoderProcess {
  readonly stdin: EncoderSink;
  readonly stdout: ReadableStream<Uint8Array>;
  readonly exited: Promise<number>;
  kill(signal?: NodeJS.Signals | number): void;
}

export type EncoderSpawn = (command: string[]) => EncoderProcess;

export interface JpegEncoderOptions {
  width: number;
  height: number;
  quality: number;
  ffmpeg?: string;
  maxFrameBytes?: number;
}

type Pending = { resolve: (jpeg: Uint8Array) => void; reject: (error: Error) => void };

function defaultSpawn(command: string[]): EncoderProcess {
  const proc = Bun.spawn(command, { stdin: "pipe", stdout: "pipe", stderr: "inherit" });
  if (!proc.stdin || typeof proc.stdin === "number") throw new Error("JPEG encoder stdin unavailable");
  if (!proc.stdout || typeof proc.stdout === "number") throw new Error("JPEG encoder stdout unavailable");
  return proc as unknown as EncoderProcess;
}

export class JpegEncoder {
  private readonly parser: JpegStreamParser;
  private readonly frameBytes: number;
  private readonly command: string[];
  private proc?: EncoderProcess;
  private pending?: Pending;
  private failure?: Error;
  private closed = false;
  private stopping?: Promise<void>;

  constructor(private readonly options: JpegEncoderOptions, private readonly spawn: EncoderSpawn = defaultSpawn) {
    const { width, height, quality } = options;
    if (!Number.isInteger(width) || width < 1 || !Number.isInteger(height) || height < 1) {
      throw new Error("invalid JPEG encoder dimensions");
    }
    this.frameBytes = width * height * 3;
    this.parser = new JpegStreamParser(options.maxFrameBytes);
    this.command = [
      options.ffmpeg ?? "ffmpeg", "-hide_banner", "-loglevel", "error",
      "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", `${width}x${height}`, "-i", "pipe:0",
      "-q:v", String(jpegQualityToQ(quality)), "-f", "image2pipe", "-vcodec", "mjpeg", "pipe:1",
    ];
  }

  start(): void {
    if (this.closed) throw new Error("JPEG encoder is stopped");
    if (this.proc) throw new Error("JPEG encoder already started");
    const proc = this.spawn(this.command);
    this.proc = proc;
    void this.read(proc);
    void proc.exited.then(
      code => this.handleExit(proc, code),
      error => { if (this.proc === proc && !this.closed) this.fail(error); },
    );
  }

  encode(bgr: Uint8Array): Promise<Uint8Array> {
    if (this.closed) return Promise.reject(new Error("JPEG encoder is stopped"));
    if (!this.proc) return Promise.reject(new Error("JPEG encoder is not started"));
    if (this.failure) return Promise.reject(this.failure);
    if (this.pending) return Promise.reject(new Error("JPEG encoder busy: another frame is being encoded"));
    if (bgr.byteLength !== this.frameBytes) {
      return Promise.reject(new Error(`JPEG encoder expected ${this.frameBytes} BGR bytes, got ${bgr.byteLength}`));
    }

    return new Promise<Uint8Array>((resolve, reject) => {
      const pending: Pending = { resolve, reject };
      this.pending = pending;
      try {
        const written = this.proc!.stdin.write(bgr);
        if (written instanceof Promise) {
          void written.then(
            count => { if (this.pending === pending && count !== bgr.byteLength) this.fail(new Error("JPEG encoder short input write")); },
            error => { if (this.pending === pending) this.fail(error); },
          );
        } else if (written !== bgr.byteLength) {
          this.fail(new Error("JPEG encoder short input write"));
        }
      } catch (error) {
        if (this.pending === pending) this.fail(error);
      }
    });
  }

  stop(): Promise<void> {
    if (this.stopping) return this.stopping;
    this.closed = true;
    const proc = this.proc;
    this.proc = undefined;
    const failure = this.failure ?? new Error("JPEG encoder stopped");
    this.failure = failure;
    this.rejectPending(failure);
    if (!proc) return Promise.resolve();

    try {
      const ended = proc.stdin.end?.();
      if (ended instanceof Promise) void ended.catch(() => undefined);
    } catch { /* stdin already closed */ }
    try { proc.kill("SIGTERM"); } catch { /* process already exited */ }

    this.stopping = Promise.race([
      proc.exited.then(() => undefined, () => undefined),
      Bun.sleep(1000),
    ]).then(() => { this.stopping = undefined; });
    return this.stopping;
  }

  private async read(proc: EncoderProcess): Promise<void> {
    const reader = proc.stdout.getReader();
    try {
      while (!this.closed) {
        const { value, done } = await reader.read();
        if (done) break;
        const frames = this.parser.push(value);
        for (const frame of frames) this.settle(frame);
      }
    } catch (error) {
      if (!this.closed && this.proc === proc) this.fail(error);
    } finally {
      try { reader.releaseLock(); } catch { /* already released */ }
    }
    if (!this.closed && this.proc === proc && !this.failure) this.fail(new Error("JPEG encoder stdout closed"));
  }

  private settle(frame: Uint8Array): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    pending.resolve(frame);
  }

  private rejectPending(error: Error): void {
    const pending = this.pending;
    this.pending = undefined;
    pending?.reject(error);
  }

  private fail(error: unknown): void {
    if (this.closed) return;
    const failure = error instanceof Error ? error : new Error(String(error));
    if (!this.failure) this.failure = failure;
    this.rejectPending(this.failure);
    const proc = this.proc;
    if (proc) { try { proc.kill("SIGTERM"); } catch { /* process already exited */ } }
  }

  private handleExit(proc: EncoderProcess, code: number): void {
    if (this.proc !== proc || this.closed) return;
    this.fail(new Error(`JPEG encoder exited with code ${code}`));
  }
}

