export function grayscale(bgr: Uint8Array, width: number, height: number): Uint8Array {
  if (bgr.length !== width * height * 3) throw new Error("invalid BGR frame");
  const gray = new Uint8Array(width * height);
  for (let i = 0, j = 0; j < gray.length; i += 3, j++) gray[j] = Math.round((29 * bgr[i]! + 150 * bgr[i + 1]! + 77 * bgr[i + 2]!) / 256);
  return gray;
}

export interface LetterboxResult {
  rgb: Uint8Array;
  scale: number;
  padX: number;
  padY: number;
  sourceWidth: number;
  sourceHeight: number;
}

/** Nearest-neighbor BGR24 to RGB NHWC letterbox. A fixed 640 square matches the model. */
export function letterbox(bgr: Uint8Array, width: number, height: number, size = 640): LetterboxResult {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1 || bgr.length !== width * height * 3) throw new Error("invalid BGR frame");
  const scale = Math.min(size / width, size / height);
  const outW = Math.round(width * scale), outH = Math.round(height * scale);
  const padX = Math.floor((size - outW) / 2), padY = Math.floor((size - outH) / 2);
  const rgb = new Uint8Array(size * size * 3);
  rgb.fill(114);
  for (let y = 0; y < outH; y++) {
    const sy = Math.min(height - 1, Math.floor(y / scale));
    for (let x = 0; x < outW; x++) {
      const sx = Math.min(width - 1, Math.floor(x / scale));
      const src = (sy * width + sx) * 3, dst = ((y + padY) * size + x + padX) * 3;
      rgb[dst] = bgr[src + 2]!; rgb[dst + 1] = bgr[src + 1]!; rgb[dst + 2] = bgr[src]!;
    }
  }
  return { rgb, scale, padX, padY, sourceWidth: width, sourceHeight: height };
}

export const enum PacketType { Frame = 1, Detection = 2, Control = 3, Ack = 4 }
export type Packet = { type: PacketType; payload: Uint8Array };
export function encodePacket(type: PacketType, payload: Uint8Array): Uint8Array {
  const out = new Uint8Array(5 + payload.length);
  out[0] = type;
  new DataView(out.buffer).setUint32(1, payload.length, true);
  out.set(payload, 5);
  return out;
}
export class PacketDecoder {
  private buffer = new Uint8Array();
  push(chunk: Uint8Array): Packet[] {
    const joined = new Uint8Array(this.buffer.length + chunk.length);
    joined.set(this.buffer); joined.set(chunk, this.buffer.length);
    this.buffer = joined;
    const packets: Packet[] = [];
    while (this.buffer.length >= 5) {
      const size = new DataView(this.buffer.buffer, this.buffer.byteOffset).getUint32(1, true);
      if (size > 16 * 1024 * 1024) throw new Error('IPC packet too large');
      if (this.buffer.length < size + 5) break;
      packets.push({ type: this.buffer[0] as PacketType, payload: this.buffer.slice(5, size + 5) });
      this.buffer = this.buffer.slice(size + 5);
    }
    return packets;
  }
}
export class FrameWindow {
  private pending = new Map<number, number>();
  private queue: { seq: number; data: Uint8Array }[] = [];
  dropped = 0;
  offer(seq: number, data: Uint8Array): void {
    this.queue.push({ seq, data });
    if (this.queue.length > 2) { this.queue.shift(); this.dropped++; }
  }
  flush(send: (data: Uint8Array) => void, now = Date.now()): void {
    while (this.pending.size < 2 && this.queue.length) {
      const item = this.queue.shift()!;
      send(item.data); this.pending.set(item.seq, now);
    }
  }
  ack(seq: number): void { this.pending.delete(seq); }
  stalled(now = Date.now()): boolean { return [...this.pending.values()].some(t => now - t > 30000); }
  get inFlight(): number { return this.pending.size; }
}

import { expect, test } from "bun:test";
import { letterbox } from "../src/preprocess";
import { decodeFp16, fp16Table, nms } from "../src/yolo";
import { grayscale } from "../src/tag_worker";
import { NpuLock } from "../src/rknn";
import { existsSync } from "node:fs";

test("letterbox swaps BGR and centers aspect ratio", () => {
  const image = letterbox(new Uint8Array([1, 2, 3, 4, 5, 6]), 2, 1, 4);
  expect([image.scale, image.padY]).toEqual([2, 1]);
  expect(Array.from(image.rgb.slice(12, 18))).toEqual([3, 2, 1, 3, 2, 1]);
});
test("FP16 lookup covers normal values", () => {
  expect(fp16Table()[0x3c00]).toBe(1);
  expect(fp16Table()[0xc000]).toBe(-2);
});
test("NMS is class scoped", () => {
  const a = {label:"a", classId:1, confidence:0.9, x:0,y:0,width:10,height:10};
  expect(nms([a, {...a, confidence:0.8}, {...a, classId:2}], 0.5)).toHaveLength(2);
});
test("decoder rejects invalid output", () => {
  const meta = letterbox(new Uint8Array(3), 1, 1);
  expect(() => decodeFp16(new Uint16Array(0), meta, new Set([0]))).toThrow();
});
test("grayscale length", () => expect(grayscale(new Uint8Array([0,0,0]),1,1)).toEqual(new Uint8Array([0])));
test("NPU lock rejects a second owner and releases", () => {
  const path = `/tmp/kitti-npu-test-${process.pid}-${Math.random()}.lock`;
  const first = new NpuLock(path), second = new NpuLock(path);
  try { first.acquire(); expect(() => second.acquire()).toThrow(/live PID/); }
  finally { first.release(); }
  expect(existsSync(path)).toBe(false);
});

import { test, expect } from 'bun:test';
import { MockGpio, parsePin, type DigitalIo, type Pin } from '../src/gpio';
import { GpioRelay, MockRelay, Pump } from '../src/pump';
import { Stepper, MOTOR_PINS } from '../src/stepper';
import { Manual } from '../src/manual';

class RecordingGpio implements DigitalIo {
  readonly events: string[] = [];
  private readonly inner = new MockGpio();
  output(pin: Pin, initial: boolean) { this.events.push(`output:${pin}:${initial}`); this.inner.output(pin, initial); }
  input(pin: Pin, pullUp: boolean) { this.events.push(`input:${pin}:${pullUp}`); this.inner.input(pin, pullUp); }
  write(pin: Pin, high: boolean) { this.events.push(`write:${pin}:${high}`); this.inner.write(pin, high); }
  read(pin: Pin) { return this.inner.read(pin); }
  close() { this.events.push('close'); this.inner.close(); }
}

test('pin offsets', () => { expect(parsePin('GPIO1_C6')).toEqual({ bank: 1, offset: 22, global: 54 }); });

test('relay boots off and times out', async () => {
  const io = new MockGpio();
  const relay = new GpioRelay(io, 'GPIO1_C6', false);
  expect(io.values.get('GPIO1_C6')).toBe(true);
  const pump = new Pump(relay, { minPulseMs: 5, maxPulseMs: 100, maxContinuousMs: 20 });
  pump.start();
  expect(pump.on).toBe(true);
  await Bun.sleep(35);
  expect(pump.on).toBe(false);
  expect(io.values.get('GPIO1_C6')).toBe(true);
  pump.close();
});

test('configured axes are force-disabled before any enable', () => {
  const io = new MockGpio();
  const yaw = new Stepper(io, MOTOR_PINS.yaw);
  const pitch = new Stepper(io, MOTOR_PINS.pitch);
  expect(io.modes.size).toBe(0);
  yaw.forceDisable();
  pitch.forceDisable();
  for (const pins of [MOTOR_PINS.yaw, MOTOR_PINS.pitch]) {
    expect(io.modes.get(pins.en)).toBe('output');
    expect(io.values.get(pins.en)).toBe(true);
    expect(io.modes.get(pins.step)).toBe('output');
    expect(io.modes.get(pins.dir)).toBe('output');
  }
  yaw.enable();
  expect(io.values.get(MOTOR_PINS.yaw.en)).toBe(false);
  yaw.disable();
  expect(io.values.get(MOTOR_PINS.yaw.en)).toBe(true);
});

test('pump runs without a yaw switch mapping or manual axes', () => {
  const relay = new MockRelay();
  const pump = new Pump(relay, { minPulseMs: 5, maxPulseMs: 100, maxContinuousMs: 100 });
  pump.start(5);
  expect(pump.on).toBe(true);
  expect(relay.on).toBe(true);
  pump.close();
  expect(relay.on).toBe(false);
});

test('final relay off is written before shared GPIO release', () => {
  const io = new RecordingGpio();
  const relay = new GpioRelay(io, 'GPIO1_C6', false);
  const pump = new Pump(relay, { minPulseMs: 5, maxPulseMs: 100, maxContinuousMs: 100 });
  pump.start(5);
  pump.close();
  io.close();
  const writes = io.events.map((event, index) => ({ event, index })).filter(({ event }) => event.startsWith('write:GPIO1_C6:'));
  const last = writes.at(-1)!;
  expect(last.event).toBe('write:GPIO1_C6:true');
  expect(last.index).toBeLessThan(io.events.indexOf('close'));
});

test('estop force-disables untouched drivers and pump', () => {
  const io = new MockGpio();
  const yaw = new Stepper(io, MOTOR_PINS.yaw);
  const pitch = new Stepper(io, MOTOR_PINS.pitch);
  const relay = new MockRelay();
  const pump = new Pump(relay);
  const manual = new Manual({ yaw, pitch }, pump, io);
  manual.enable(true);
  pump.start();
  manual.estop();
  expect(io.values.get(MOTOR_PINS.yaw.en)).toBe(true);
  expect(io.values.get(MOTOR_PINS.pitch.en)).toBe(true);
  expect(relay.on).toBe(false);
});

test('manual shutdown leaves shared GPIO open for pump final off', () => {
  const io = new MockGpio();
  const relay = new MockRelay();
  const pump = new Pump(relay);
  const axes = { yaw: new Stepper(io, MOTOR_PINS.yaw), pitch: new Stepper(io, MOTOR_PINS.pitch) };
  const manual = new Manual(axes, pump, io);
  manual.shutdown();
  pump.close();
  expect(io.modes.size).toBeGreaterThan(0);
  io.close();
  expect(io.modes.size).toBe(0);
});

test('step cap', async () => {
  const io = new MockGpio();
  const m = new Stepper(io, MOTOR_PINS.yaw, { maxRate: 1000, acceleration: 10000, pulseUs: 10, maxSteps: 2 });
  m.enable();
  expect(m.move(1, 3, 100)).rejects.toThrow();
});

export type Config = {
  host: string; port: number; socket: string; model: string; camera: string;
  width: number; height: number; fps: number; jpegQuality: number;
  relayActiveHigh: boolean | null; yawNegativeSwitch: string | null;
  maxPumpMs: number; pulseMs: number; maxSteps: number;
};

const number = (name: string, fallback: number, min: number, max: number) => {
  const value = Number(process.env[name] ?? fallback);
  if (!Number.isFinite(value) || value < min || value > max) throw new Error(`${name} must be ${min}..${max}`);
  return value;
};

export function loadConfig(): Config {
  const polarity = process.env.KITTI_RELAY_ACTIVE_HIGH;
  if (polarity !== undefined && polarity !== '0' && polarity !== '1') throw new Error('KITTI_RELAY_ACTIVE_HIGH must be 0 or 1');
  return {
    host: process.env.KITTI_HOST ?? '127.0.0.1',
    port: number('KITTI_PORT', 8080, 1, 65535),
    socket: process.env.KITTI_SOCKET ?? '/tmp/kitti-turret.sock',
    model: process.env.KITTI_MODEL ?? '', camera: process.env.KITTI_CAMERA ?? 'auto',
    width: number('KITTI_WIDTH', 640, 64, 4096), height: number('KITTI_HEIGHT', 480, 64, 4096),
    fps: number('KITTI_FPS', 20, 1, 120), jpegQuality: number('KITTI_JPEG_QUALITY', 60, 1, 100),
    relayActiveHigh: polarity === undefined ? null : polarity === '1',
    yawNegativeSwitch: process.env.KITTI_YAW_NEGATIVE_SWITCH ?? null,
    maxPumpMs: number('KITTI_MAX_PUMP_MS', 10000, 50, 60000),
    pulseMs: number('KITTI_PULSE_MS', 500, 50, 2000),
    maxSteps: number('KITTI_MAX_STEPS', 57600, 1, 1000000)
  };
}

