        </select></label>
        <label>Aim X <input id="aim-x" type="range" min="0" max="100" value={Math.round(aimX * 100)} onChange={e => { const v = Number(e.target.value) / 100; setAimX(v); send({ type: 'aim', x: v, y: aimY }); }} /></label>
